const rows = $input.all().map(i => i.json);
const failed = rows.filter(r => !r.ok);
const lines = rows.map(r => `${r.ok ? '\u2705' : '\u274c'} ${r.check_name} / ${r.entity}: ${r.value}`);
const header = failed.length === 0
  ? '\u2705 AI Data Quality Report \u2014 \u0432\u0441\u0451 \u0447\u0438\u0441\u0442\u043e'
  : `\u26a0\ufe0f AI Data Quality Report \u2014 ${failed.length} \u043f\u0440\u043e\u0432\u0430\u043b\u0435\u043d\u043e(\u0439) \u0438\u0437 \u0441\u0442\u0440\u043e\u044f`;
const message = [header, '', ...lines].join('\n');
return [{ json: { ok: failed.length === 0, failed_count: failed.length, message } }];
